/**
 * Unit tests for AnnotationIntrospector.refineSerializationType
 */
public class AnnotationIntrospector_refineSerializationType_TriageGen1Test {

    @Mock
    private AnnotationIntrospector introspector;

    @Mock
    private MapperConfig<?> config;

    @Mock
    private Annotated annotated;

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        typeFactory = TypeFactory.defaultInstance();
        when(config.getTypeFactory()).thenReturn(typeFactory);
        when(annotated.getName()).thenReturn("testAnnotation");
    }

    /**
     * Test case where no refinement is found.
     */
    @Test
    public void testRefineSerializationType_NoChanges() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);

        when(introspector.findSerializationType(annotated)).thenReturn(null);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(baseType, result);
    }

    /**
     * Test case where the main type is refined via widening (constructGeneralizedType).
     */
    @Test
    public void testRefineSerializationType_WidenMainType() throws JsonMappingException {
        // Base type is Object, Annotation says String
        JavaType baseType = typeFactory.constructType(Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(String.class, result.getRawClass());
    }

    /**
     * Test case where the main type is refined via static typing (hasRawClass matches).
     */
    @Test
    public void testRefineSerializationType_StaticTypingMain() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);
        when(introspector.findSerializationType(annotated)).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertTrue(result.hasStaticTyping());
    }

    /**
     * Test case for Map-like types: Refining the Key Type (Widening).
     */
    @Test
    public void testRefineSerializationType_RefineMapKeyWiden() throws JsonMappingException {
        // Map<Object, ?> -> Map<String, ?>
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);

        when(introspector.findSerializationType(annotated)).thenReturn(HashMap.class);
        when(introspector.findSerializationKeyType(eq(annotated), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(String.class, result.getKeyType().getRawClass());
    }

    /**
     * Test case for Map-like types: Refining the Key Type (Specialization/Narrowing).
     */
    @Test
    public void testRefineSerializationType_RefineMapKeySpecialize() throws JsonMappingException {
        // Map<String, ?> -> Map<Object, ?> (Specialization case: currRaw is assignable from keyClass)
        // Note: The logic is: if (keyClass.isAssignableFrom(currRaw)) -> Generalized, 
        // else if (currRaw.isAssignableFrom(keyClass)) -> Specialized.
        // To trigger Specialized: currRaw (Object) is assignable from keyClass (String) is false.
        // Wait, if keyClass is String and currRaw is Object: Object.class.isAssignableFrom(String.class) is TRUE.

        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(HashMap.class);
        when(introspector.findSerializationKeyType(eq(annotated), any(JavaType.class))).thenReturn(String.class);

        // Let's force a specialization: base is Map<String, Object>, annotation says use Object as key
        JavaType baseType2 = typeFactory.constructMapType(HashMap.class, String.class, Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(HashMap.class);
        when(introspector.findSerializationKeyType(eq(annotated), any(JavaType.class))).thenReturn(Object.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType2);
        assertEquals(Object.class, result.getKeyType().getRawClass());
    }

    /**
     * Test case for Map-like types: Unrelated Key Type (Throws Exception).
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_UnrelatedKeyType() throws JsonMappingException {
        JavaType baseType = typeFactory.constructMapType(HashMap.class, String.class, Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(HashMap.class);
        // String and Integer are unrelated
        when(introspector.findSerializationKeyType(eq(annotated), any(JavaType.class))).thenReturn(Integer.class);

        introspector.refineSerializationType(config, annotated, baseType);
    }

    /**
     * Test case for Container types: Refining the Content Type (Widening).
     */
    @Test
    public void testRefineSerializationType_RefineContentTypeWiden() throws JsonMappingException {
        // List<Object> -> List<String>
        JavaType baseType = typeFactory.constructCollectionType(java.util.ArrayList.class, Object.class);

        when(introspector.findSerializationType(annotated)).thenReturn(java.util.ArrayList.class);
        when(introspector.findSerializationContentType(eq(annotated), any(JavaType.class))).thenReturn(String.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(String.class, result.getContentType().getRawClass());
    }

    /**
     * Test case for Container types: Refining the Content Type (Specialization).
     */
    @Test
    public void testRefineSerializationType_RefineContentTypeSpecialize() throws JsonMappingException {
        // List<String> -> List<Object> (Specialization: String.class.isAssignableFrom(Object.class) is false, 
        // but Object.class.isAssignableFrom(String.class) is true)
        JavaType baseType = typeFactory.constructCollectionType(java.util.ArrayList.class, String.class);

        when(introspector.findSerializationType(annotated)).thenReturn(java.util.ArrayList.class);
        when(introspector.findSerializationContentType(eq(annotated), any(JavaType.class))).thenReturn(Object.class);

        JavaType result = introspector.refineSerializationType(config, annotated, baseType);

        assertEquals(Object.class, result.getContentType().getRawClass());
    }

    /**
     * Test case for Container types: Unrelated Content Type (Throws Exception).
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_UnrelatedContentType() throws JsonMappingException {
        JavaType baseType = typeFactory.constructCollectionType(java.util.ArrayList.class, String.class);

        when(introspector.findSerializationType(annotated)).thenReturn(java.util.ArrayList.class);
        // String and Integer are unrelated
        when(introspector.findSerializationContentType(eq(annotated), any(JavaType.class))).thenReturn(Integer.class);

        introspector.refineSerializationType(config, annotated, baseType);
    }

    /**
     * Test case for IllegalArgumentException during widening (Internal Error Path).
     */
    @Test(expected = JsonMappingException.class)
    public void testRefineSerializationType_IllegalArgumentException() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(Object.class);
        when(introspector.findSerializationType(annotated)).thenReturn(String.class);

        // Mock typeFactory to throw exception when trying to construct a type
        TypeFactory mockTf = mock(TypeFactory.class);
        when(config.getTypeFactory()).thenReturn(mockTf);
        when(mockTf.constructGeneralizedType(any(), any())).thenThrow(new IllegalArgumentException("Mock error"));

        introspector.refineSerializationType(config, annotated, baseType);
    }
}
